-- Apanhado LABIC 2025 enviado pela coordenação (10/11/2026). Pode ser executado mais de uma vez.
begin;
update public.projetos set resumo='Sistema de resfriamento automatizado para gado leiteiro, voltado ao bem-estar animal e ao aumento da produtividade.' where slug='monitoramento-de-gado-leiteiro' and resumo='Monitoramento de rebanho leiteiro voltado ao bem-estar animal e à produtividade.';
update public.projetos set resumo='Sistema de detecção de compostos voláteis aplicado à diferenciação de cafés.' where slug='nariz-eletronico' and resumo='Conjunto de sensores de gás que reconhece odores.';
update public.projetos set resumo='Dispositivo de comunicação para estimular a linguagem oral.' where slug='estimulador-de-fala' and resumo='Dispositivo de apoio ao estímulo da fala.';
update public.projetos set resumo='Robô manipulador espelhado, controlado em tempo real por um gêmeo mecânico.' where slug='gemeo-mecanico' and resumo='Mecanismo que reproduz, em tempo real, os movimentos de um operador.';
update public.projetos set resumo='Estimativa de pose para controlar drones em tempo real, numa interface natural feita com MediaPipe e OpenCV.' where slug='estimacao-de-pose' and resumo='Visão computacional para estimar a posição e a orientação de objetos e pessoas.';
update public.projetos set resumo='Sistema de controle por voz para cadeiras de rodas motorizadas.' where slug='sistema-para-cadeiras-de-rodas' and resumo='Sistema embarcado para dar mais autonomia a usuários de cadeiras de rodas.';
update public.projetos set resumo='Dispositivo multissensor que coleta dados ambientais da cidade em tempo real para apoiar decisões.' where slug='dispositivo-de-sensores-ambientais' and resumo='Estação compacta para medir variáveis do ambiente.';
update public.projetos set resumo='Luva Mágica: uma luva que controla um robô pelo movimento da mão.' where slug='controlador-vestivel' and resumo='Controle que se veste no corpo para comandar dispositivos por movimento.';
update public.projetos set resumo='Veículo subaquático operado remotamente, de baixo custo, feito para o ensino de STEM em escolas públicas.' where slug='rov' and resumo='Veículo subaquático operado remotamente para inspeção e ensino.';
update public.projetos set resumo='Protótipo de comunicação por luz visível (VLC) para aplicações educacionais.' where slug='vlc' and resumo='Comunicação por luz visível: dados transmitidos pela iluminação.';
update public.projetos set resumo='Peixe robô de baixo custo, feito com impressão 3D, que segue a luz.' where slug='peixe-robo' and resumo='Robô submarino em miniatura com formato e nado de peixe.';
update public.projetos set resumo='Robô seguidor de linha autônomo com sensor de obstáculo, para fins educacionais.' where slug='seguidor-de-linha' and resumo='Robô autônomo que percorre um trajeto guiado por uma linha no chão.';
update public.iniciativas set nome='LearnBots', descricao='Desenvolvido pela Nyquist Educational Games. Aprovado na Etapa 2 do Catalisa ICT, Ciclo 02.' where slug='nyquist' and nome='Nyquist';
update public.conquistas set descricao=replace(descricao,'CleanBoiler, EasyRide, Nyquist, AquaFeed e AccessSim','CleanBoiler, EasyRide, LearnBots (Nyquist), AquaFeed e AccessSim') where titulo='Cinco projetos aprovados na 2ª fase do Catalisa ICT';
update public.marcos set descricao=replace(descricao,'CleanBoiler, EasyRide, Nyquist, AquaFeed e AccessSim','CleanBoiler, EasyRide, LearnBots, AquaFeed e AccessSim') where titulo='Cinco projetos avançam no Catalisa ICT';
update public.iniciativas set descricao=trim(descricao || ' Participante do Startup Nordeste em 2025.'), ano=coalesce(ano,2025) where slug='ada-amiga-das-maes' and descricao not like '%Startup Nordeste%';
update public.iniciativas set descricao=trim(descricao || ' Participante do Startup Nordeste em 2025.'), ano=coalesce(ano,2025) where slug='aquafeed' and descricao not like '%Startup Nordeste%';
update public.iniciativas set descricao=trim(descricao || ' Participante do Startup Nordeste em 2025.'), ano=coalesce(ano,2025) where slug='easyride' and descricao not like '%Startup Nordeste%';
commit;
select (select count(*) from public.projetos) projetos, (select count(*) from public.conquistas) conquistas, (select count(*) from public.conquistas where ano=2025) conquistas_2025, (select count(*) from public.conquistas where tipo='EVENTO' and ano=2025) trabalhos_mnr_snct, (select count(*) from public.conquistas where projeto_id is not null) ligadas_a_projeto, (select count(*) from public.marcos) marcos, (select nome from public.iniciativas where slug='nyquist') startup;
